def is_perpendicular(n, d1, d2):
    # d1 = (a, b), d2 = (c, d)
    # Check if (a+b-c-d) = n*(2k+1)/2
    # That is, 2*(a+b-c-d) = n*(2k+1)
    # Which means 2*(a+b-c-d) is an odd multiple of n
    # Or simply, 2*(a+b-c-d) % (2*n) == n
    a, b = d1
    c, d = d2
    val = 2 * (a + b - c - d)
    return val % (2 * n) == n

def solve_for_n(n):
    diagonals = []
    for i in range(n):
        for j in range(i + 2, n):
            if i == 0 and j == n - 1:
                continue
            diagonals.append((i, j))

    any_perpendicular = False
    for i in range(len(diagonals)):
        for j in range(i + 1, len(diagonals)):
            if is_perpendicular(n, diagonals[i], diagonals[j]):
                any_perpendicular = True
                break
        if any_perpendicular:
            break

    return any_perpendicular

for n in [3, 5, 7, 9, 11]:
    print(f"n={n}, any_perpendicular={solve_for_n(n)}")
